// App members: explicit current-profile selection; original version files remain intact.
void requestTrainingVersions(){if(!developer())throw std::runtime_error("학습 버전 관리는 개발자 권한이 필요합니다.");if(learningBusy||repairActive||engine->busy)throw std::runtime_error("현재 작업을 마친 뒤 버전을 선택하세요.");featureRequest("model_versions","GET","/learning/profiles/"+activeProfile()+"/model-versions");}
void showTrainingVersions(const json& data){auto profile=activeProfile();if(!developer()||str(data,"profile_id")!=profile||!sheetHash(str(data,"content_version")))return;HMENU menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING|(flag(data,"using_base")?MF_CHECKED:0),1,L"학습 가중치 해제 · 파일 보존");auto rows=data.value("versions",json::array());for(size_t i=0;i<rows.size();i++){auto& row=rows[i];std::wstring title=flag(row,"current")?L"현재 · ":L"";title+=wide(str(row,"created","과거 버전"));if(row.value("steps",json(nullptr)).is_number_integer())title+=L" · "+std::to_wstring(row["steps"].get<int>())+L" steps";title+=L" · "+wide(str(row,"message"));AppendMenuW(menu,MF_STRING|(!flag(row,"restorable")?MF_GRAYED:0),i+10,title.c_str());}if(rows.empty())AppendMenuW(menu,MF_STRING|MF_GRAYED,0,L"저장된 학습 버전이 없습니다.");POINT point;GetCursorPos(&point);int choice=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,point.x,point.y,0,hwnd,nullptr);DestroyMenu(menu);json version=nullptr;if(choice==1){}else if(choice>=10&&size_t(choice-10)<rows.size()&&flag(rows[choice-10],"restorable")){auto selectedVersion=str(rows[choice-10],"id");if(!boardId(selectedVersion))throw std::runtime_error("학습 버전 ID를 확인할 수 없습니다.");version=selectedVersion;}else return;if(MessageBoxW(hwnd,L"이 학습 버전을 사용할까요?\n이전 가중치와 학습 이미지는 보존하며 자동 학습은 꺼집니다.\n서버가 파일 SHA와 기반 구조를 다시 확인하고, GPU 사용 중이면 변경하지 않습니다.",L"학습 버전 선택",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;featureRequest("model_version_selected","POST","/learning/profiles/"+profile+"/model-version",{{"version",version},{"expected_version",data["content_version"]}});}
